"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["47651"],{472343(e){e.exports=JSON.parse('{"id":7291,"title":"\u91D1\u878D\u76F8\u5173\u6CD5\u5F8B\u6587\u4EF6\u5206\u6790","description":"\u4F60\u662F\u4E00\u4E2A\u6CD5\u5F8B\u548C\u91D1\u878D\u4E13\u5BB6\uFF0C\u200B\u4EFB\u52A1\u76EE\u6807\uFF1A\u200B\u200B \u57FA\u4E8E\u6211\u4E0A\u4F20\u7684\u4E09\u4EFD\u9999\u6E2F\u8054\u4EA4\u6240\u4E0A\u5E02\u7533\u8BF7\u6587\u4EF6\uFF08\u5982\u62DB\u80A1\u4E66\uFF09\uFF0C\u64B0\u5199\u4E00\u4EFD\u5206\u6790\u62A5\u544A\u3002\u8F93\u51FA\u7ED3\u679C\uFF1A\u4E00\u4EFD\u8BE6\u7EC6\u7684\u5206\u6790\u62A5\u544A\uFF0C\u4EE5\u53CA\u4E00\u4EFD\u7B80\u8981\u7684\u7ED9\u6295\u8D44\u8005\u7684ABC\u6587\u4EF6\u3002\u200B\u6838\u5FC3\u5206\u6790\u4E3B\u9898\uFF1A\u200B\u200B \u91CD\u70B9\u5206\u6790\u8FD9\u4E9B\u516C\u53F8\u5728\u9999\u6E2F\u8054\u4EA4\u6240\u4E0A\u5E02\u524D\u8FDB\u884C\u7684\u80A1\u6743\u8F6C\u8BA9\u884C\u4E3A\uFF0C\u5305\u62EC\uFF1A1\u3001\u200B\u589E\u8D44\u6269\u80A1\u200B\uFF08\u65B0\u6295\u8D44\u8005\u8BA4\u8D2D\u65B0\u80A1\uFF09\uFF1B2\u3001\u200B\u8001\u80A1\u8F6C\u8BA9\u200B\uFF08\u73B0\u6709\u80A1\u4E1C\u51FA\u552E\u6240\u6301\u80A1\u4EFD\uFF09\uFF1B3\u3001\u5176\u4ED6\u60C5\u51B5\u3002\u200B\u5206\u6790\u8303\u56F4\uFF1A\u200B\u200B1\u3001\u200B\u653F\u7B56\u89C4\u5B9A\uFF1A\u200B\u200B \u7CFB\u7EDF\u68B3\u7406\u5E76\u89E3\u8BFB\u9999\u6E2F\u8054\u4EA4\u6240\u9488\u5BF9\u4E0A\u8FF0\u4E0A\u5E02\u524D\u80A1\u6743\u8F6C\u8BA9\u884C\u4E3A\u7684\u6240\u6709\u76F8\u5173\u4E0A\u5E02\u89C4\u5219\u3001\u6307\u5F15\u53CA\u653F\u7B56\u8981\u6C42\u3002\u200B2\u3001\u5408\u89C4\u8981\u6C42\uFF1A\u200B\u200B \u5206\u6790\u8FD9\u4E9B\u8F6C\u8BA9\u884C\u4E3A\u9700\u8981\u6EE1\u8DB3\u54EA\u4E9B\u5177\u4F53\u7684\u5408\u89C4\u6761\u4EF6\u200B\uFF08\u4F8B\u5982\uFF0C\u5B9A\u4EF7\u516C\u5141\u6027\u3001\u4FE1\u606F\u62AB\u9732\u8981\u6C42\u3001\u80A1\u4E1C\u8D44\u683C\u786E\u8BA4\u7B49\uFF09\u3002 3\u3001\u6295\u8D44\u8005\u9650\u5236\uFF1A\u200B\u200B \u7279\u522B\u5173\u6CE8\u76F8\u5173\u89C4\u5219\u4E2D\u5BF9\u6295\u8D44\u8005\u8EAB\u4EFD\u3001\u6570\u91CF\u6216\u8D44\u683C\u53EF\u80FD\u5B58\u5728\u7684\u9650\u5236\u6216\u8981\u6C42\u3002 4\u3001\u5176\u4ED6\u4E0E\u6295\u8D44\u8005\u6216\u8005\u516C\u53F8\u76F8\u5173\u7684\u653F\u7B56\u3002\u200B\u62A5\u544A\u6838\u5FC3\u53D7\u4F17\u4E0E\u76EE\u6807\uFF1A\u200B\u200B \u62A5\u544A\u9762\u5411\u4E2D\u56FD\u5927\u9646\u80CC\u666F\u7684\u6295\u8D44\u8005\u3002\u6838\u5FC3\u76EE\u6807\u662F\uFF1A1\u3001\u200B\u63ED\u793A\u6295\u8D44\u98CE\u9669\u70B9\uFF1A\u200B\u200B \u6E05\u6670\u9610\u8FF0\u5883\u5185\u6295\u8D44\u8005\u82E5\u5728\u4E0A\u5E02\u524D\u9636\u6BB5\u200B\uFF08\u5373Pre-IPO\u9636\u6BB5\uFF09\u53C2\u4E0E\u6B64\u7C7B\u80A1\u6743\u8F6C\u8BA9\uFF08\u5982\u8BA4\u8D2D\u589E\u8D44\u3001\u63A5\u624B\u8001\u80A1\uFF09\uFF0C\u9700\u7279\u522B\u6CE8\u610F\u54EA\u4E9B\u5173\u952E\u4E8B\u9879\u53CA\u6F5C\u5728\u98CE\u9669\u3002\u200B\u5173\u952E\u5206\u6790\u70B9\uFF08\u6295\u8D44\u8005\u5173\u5207\u4E8B\u9879\uFF09\uFF1A\u200B\u200B\u8BF7\u52A1\u5FC5\u5728\u62A5\u544A\u4E2D\u6DF1\u5165\u5206\u6790\u4EE5\u4E0B\u6295\u8D44\u8005\u9AD8\u5EA6\u5173\u6CE8\u7684\u5177\u4F53\u4E8B\u9879\u200B\uFF1A 1\u3001\u200B\u4E0A\u5E02\u540E\u80A1\u4EFD\u7981\u552E\u671F (Lock-up Period)\uFF1A\u200B\u200B\u5206\u6790\u8054\u4EA4\u6240\u5BF9\u6B64\u7C7B\u5728\u4E34\u8FD1\u4E0A\u5E02\u524D\uFF08\u7279\u522B\u662F\u63D0\u4EA4A1\u540E/\u4E0A\u5E02\u7533\u8BF7\u540E\uFF09\u200B\u200B \u8FDB\u5165\u7684\u65B0\u80A1\u4E1C\u662F\u5426\u6709\u660E\u786E\u7684\u6CD5\u5B9A\u9501\u5B9A\u671F\u8981\u6C42\u200B\uFF1F\u65F6\u957F\u662F\u591A\u4E45\uFF1F\u662F\u5426\u5B58\u5728\u4EA4\u6613\u6240\u6216\u60EF\u4F8B\u6027\u7684\u81EA\u613F\u9501\u5B9A\u671F\u8981\u6C42\uFF1F\u5E38\u89C1\u65F6\u957F\u591A\u957F\uFF1F \u9501\u5B9A\u671F\u9650\u5236\u5BF9\u6295\u8D44\u8005\u9000\u51FA\u6D41\u52A8\u6027\u7684\u5177\u4F53\u5F71\u54CD\u3002 2\u3001\u200B\u5BF9\u4E0A\u5E02\u65F6\u95F4\u8868\u7684\u5F71\u54CD\uFF1A\u200B\u200B\u8FD9\u7C7B\u80A1\u6743\u8F6C\u8BA9\u884C\u4E3A\uFF08\u7279\u522B\u662F\u89C4\u6A21\u8F83\u5927\u3001\u6D89\u53CA\u7279\u6B8A\u6295\u8D44\u8005\u3001\u5B9A\u4EF7\u590D\u6742\u6216\u65F6\u95F4\u70B9\u654F\u611F\u7684\u4EA4\u6613\uFF09\u53EF\u80FD\u5982\u4F55\u5F71\u54CD\u6216\u5EF6\u8BEF\u516C\u53F8\u7684\u6574\u4F53\u4E0A\u5E02\u8FDB\u7A0B\u200B\uFF1F\u5206\u6790\u8054\u4EA4\u6240\u5BA1\u6838\u6B64\u7C7B\u4EA4\u6613\u53EF\u80FD\u4EA7\u751F\u7684\u989D\u5916\u5BA1\u67E5\u65F6\u95F4\u6216\u5408\u89C4\u8981\u6C42\u3002 3\u3001\u200B\u6F5C\u5728\u5176\u4ED6\u5173\u952E\u4E8B\u9879\uFF1A\u200B\u5B9A\u4EF7\u4E0E\u4F30\u503C\u98CE\u9669\uFF1A\u200B\u200B \u4E0A\u5E02\u524D\u80A1\u6743\u8F6C\u8BA9\u7684\u5B9A\u4EF7\u4F9D\u636E\uFF1F\u4E0E\u9884\u671F\u4E0A\u5E02\u4F30\u503C\u7684\u5173\u8054\uFF1F\u5B58\u5728\u9AD8\u4F30\u7684\u98CE\u9669\uFF1F\u200B\u4FE1\u606F\u62AB\u9732\u98CE\u9669\uFF1A\u200B\u200B \u516C\u53F8\u5BF9\u5386\u53F2\u80A1\u6743\u8F6C\u8BA9\u62AB\u9732\u7684\u5145\u5206\u6027\u53CA\u51C6\u786E\u6027\uFF1F\u6295\u8D44\u8005\u81EA\u8EAB\u662F\u5426\u6709\u4E49\u52A1\u62AB\u9732\uFF08\u5982\u7A7F\u900F\u6838\u67E5\uFF09\uFF1F\u200B\u5408\u89C4\u4E0E\u8FFD\u6EAF\u5BA1\u67E5\u98CE\u9669\uFF1A\u200B\u200B \u8F6C\u8BA9\u8FC7\u7A0B\uFF08\u8D44\u91D1\u6765\u6E90\u3001\u80A1\u4E1C\u9002\u683C\u6027\u3001\u5173\u8054\u4EA4\u6613\uFF09\u662F\u5426\u5B8C\u5168\u7B26\u5408\u8054\u4EA4\u6240\u89C4\u5219\uFF1F\u4E0A\u5E02\u540E\u82E5\u53D1\u73B0\u95EE\u9898\u53EF\u80FD\u5BFC\u81F4\u4EC0\u4E48\u540E\u679C\uFF1F\u200B4\u3001\u80A1\u4E1C\u7279\u6B8A\u6743\u76CA\uFF1A\u200B\u200B \u6B64\u7C7B\u6295\u8D44\u8005\u662F\u5426\u53EF\u80FD\u83B7\u5F97\u7279\u6B8A\u6743\u5229\uFF08\u5982\u53CD\u7A00\u91CA\u3001\u4F18\u5148\u6E05\u7B97\u6743\uFF09\uFF0C\u8FD9\u4E9B\u6743\u5229\u5728\u4E0A\u5E02\u65F6\u662F\u5426\u9700\u7EC8\u6B62\uFF1F\u5982\u4F55\u5904\u7406\uFF1F\u200B5\u3001\u5206\u6790\u62A5\u544A\u8981\u6C42\uFF1A\u200B\u200B1\u3001\u200B\u7ED3\u6784\u6E05\u6670\uFF1A\u200B\u200B \u5206\u7AE0\u8282\u9610\u8FF0\u653F\u7B56\u89C4\u5B9A\u548C\u6295\u8D44\u8005\u5173\u6CE8\u70B9\uFF1B2\u3001\u200B\u8BBA\u636E\u624E\u5B9E\uFF1A\u200B\u200B \u5206\u6790\u9700\u7D27\u5BC6\u57FA\u4E8E\u4E09\u4EFD\u5177\u4F53\u6848\u4F8B\u6587\u4EF6\u548C\u8054\u4EA4\u6240\u516C\u5F00\u89C4\u5219\u539F\u6587\u30023\u3001\u200B\u7ED3\u8BBA\u660E\u786E\uFF1A\u200B\u200B \u9488\u5BF9\u5883\u5185\u6295\u8D44\u8005\uFF0C\u63D0\u51FA\u5177\u4F53\u3001\u53EF\u64CD\u4F5C\u7684 \u200B\u200B\u201C\u51B3\u7B56\u524D\u5FC5\u987B\u6838\u67E5\u4E8B\u9879\u6E05\u5355\u201D\u200B\u200B \u3002 6\u3001\u6295\u8D44\u8005ABC\u6587\u4EF6\u8981\u6C42\uFF1A\u7CBE\u7B80\uFF0C\u65B9\u4FBF\uFF0C\u4E13\u4E1A\uFF0C\u6295\u8D44\u8005\u62FF\u5230\u8FD9\u4E2A\u6587\u4EF6\u4F1A\u5F88\u5BB9\u6613\u6E05\u6670\u81EA\u5DF1\u53EF\u80FD\u9762\u4E34\u7684\u653F\u7B56\u3002","owner":"270026207@qq.com","upvotes":3,"downvotes":0,"upvoteDifference":3,"updatedAt":"2026-04-13T20:38:44.642Z"}')}}]);